const allowedTags = new Set(["p", "br", "strong", "b", "em", "i", "u", "ul", "ol", "li", "h3", "blockquote", "a"]);

/** Keep only the limited formatting generated by the Careers rich-text editor. */
export function sanitizeRichText(input: string) {
  let html = input
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/<(script|style|iframe|object|embed|svg|math)[^>]*>[\s\S]*?<\/\1\s*>/gi, "")
    .replace(/<(script|style|iframe|object|embed|svg|math)\b[^>]*\/?\s*>/gi, "");

  html = html.replace(/<\/?([a-zA-Z0-9-]+)\b([^>]*)>/g, (match, rawTag: string, attrs: string) => {
    const tag = rawTag.toLowerCase();
    if (!allowedTags.has(tag)) return "";
    if (/^<\//.test(match)) return tag === "br" ? "" : `</${tag}>`;
    if (tag === "br") return "<br>";
    if (tag !== "a") return `<${tag}>`;
    const href = attrs.match(/\bhref\s*=\s*(["'])(.*?)\1/i)?.[2] || "";
    const safeHref = /^(https?:\/\/|mailto:)/i.test(href.trim())
      ? href.trim().replace(/&/g, "&amp;").replace(/"/g, "&quot;")
      : "";
    return safeHref ? `<a href="${safeHref}" rel="nofollow noopener noreferrer">` : "<a>";
  });

  return html.trim();
}
